type Tenant struct {
	ID                           uuid.UUID          `json:"id"`
	Name                         string             `json:"name"`
	CraSpiritsLicenceNumber      string             `json:"cra_spirits_licence_number"`
	ExciseWarehouseLicenceNumber pgtype.Text        `json:"excise_warehouse_licence_number"`
	DefaultJurisdiction          string             `json:"default_jurisdiction"`
	CreatedAt                    pgtype.Timestamptz `json:"created_at"`
	UpdatedAt                    pgtype.Timestamptz `json:"updated_at"`
	// Derived from excise_warehouse_licence_number: a licensee without a warehouse licence pays at packaging (EDM3-1-1 para 29), one with a warehouse licence pays at removal.
	DutyPoint DutyPoint `json:"duty_point"`
	// First day duty_point governs. Duty events before this date used the at-removal basis, which is what has already been filed.
	DutyPointEffectiveFrom          pgtype.Date      `json:"duty_point_effective_from"`
	FilingFrequency                 FilingFrequency  `json:"filing_frequency"`
	FiscalMonthBasis                FiscalMonthBasis `json:"fiscal_month_basis"`
	FiscalMonthEndDay               pgtype.Int4      `json:"fiscal_month_end_day"`
	FiscalMonthNotificationRef      string           `json:"fiscal_month_notification_ref"`
	FilingFrequencyAuthorizationRef string           `json:"filing_frequency_authorization_ref"`
	RequireBatchRelease             bool             `json:"require_batch_release"`
	// How a fermentation's cost is apportioned across the distillation runs it was charged to. NULL means the licensee has not stated one, and WIP production value is refused rather than guessed.
	WipChargeBasis NullWipChargeBasis `json:"wip_charge_basis"`
	// How demand is projected. NULL means the licensee has not chosen one and forecasts are refused rather than guessed.
	ForecastMethod         NullForecastMethod `json:"forecast_method"`
	ForecastTrailingMonths int32              `json:"forecast_trailing_months"`
	// Whether this licensee has agreed to contribute anonymised operational figures to the cross-tenant benchmarks, and thereby to read them. Off by default and never inferred.
	BenchmarkOptIn   bool               `json:"benchmark_opt_in"`
	BenchmarkOptInAt pgtype.Timestamptz `json:"benchmark_opt_in_at"`
	BenchmarkOptInBy uuid.NullUUID      `json:"benchmark_opt_in_by"`
}

